package it.frociart.app;
import android.app.Activity;import android.graphics.Color;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.function.Consumer;import static it.frociart.app.FlowModel.*;
final class FlowLoopEditor {
 final Activity owner;final Ui.Sheet sheet;final Document project;final String functionId;final Consumer<FlowLoopBuilder.Plan> apply;
 final EditText variable,from,to,step,initialize,condition,body;final TextView preview,error,help;final Ui.Button kindButton,targetButton;final LinearLayout fields;final Ui.Button insert;
 final Map<View,View> rows=new HashMap<>();final FlowLoopBuilder.Spec[] drafts={FlowLoopBuilder.Spec.defaults(0),FlowLoopBuilder.Spec.defaults(1),FlowLoopBuilder.Spec.defaults(2)};
 final List<Edge> choices=new ArrayList<>();int active;String edgeId;boolean loading;Ui.Sheet child;
 final FlowCycle.Info editing;
 FlowLoopEditor(Activity owner,Ui.Sheet sheet,Document project,String functionId,String selectedEdge,Consumer<FlowLoopBuilder.Plan> apply){this(owner,sheet,project,functionId,selectedEdge,apply,null,null);}
 FlowLoopEditor(Activity owner,Ui.Sheet sheet,Document project,String functionId,String selectedEdge,Consumer<FlowLoopBuilder.Plan> apply,FlowCycle.Info editing,Consumer<Set<String>> select){
  this.editing=editing;
  this.owner=owner;this.sheet=sheet;this.project=project.copy();this.functionId=functionId;this.apply=apply;Document graph=FlowFunctionEditing.graph(this.project,functionId);
  for(Edge e:graph.edges)if(graph.find(e.from).kind!=END&&graph.find(e.to).kind!=START)choices.add(e);
  edgeId=choices.isEmpty()?null:choices.get(0).id;for(Edge e:choices)if(graph.find(e.from).kind==START){edgeId=e.id;break;}for(Edge e:choices)if(e.id.equals(selectedEdge))edgeId=e.id;
  targetButton=new Ui.Button(owner,"","link",0);targetButton.setTag("loop-target");targetButton.setSingleLine(false);targetButton.setMaxLines(4);sheet.body.addView(targetButton,new LinearLayout.LayoutParams(-1,-2));targetButton.setOnClickListener(v->chooseTarget());
  kindButton=new Ui.Button(owner,"Per · un intervallo di valori ▾","down",2);kindButton.setTag("loop-kind");kindButton.setSingleLine(false);sheet.body.addView(kindButton,new LinearLayout.LayoutParams(-1,-2));kindButton.setOnClickListener(v->chooseKind());
  help=Ui.note(owner,"");sheet.body.addView(help);fields=Ui.column(owner);sheet.body.addView(fields);
  variable=field("Variabile contatore","i",false,8192);from=field("Da (incluso)","1",false,8192);to=field("A (incluso)","5",false,8192);step=field("Passo · negativo per contare all'indietro","1",false,8192);initialize=field("Prima del ciclo · facoltativo","i = 0",false,8192);condition=field("Continua mentre la condizione è vera","i < 5",false,8192);body=field("Corpo del ciclo · una istruzione per riga","STAMPA i",true,32768);
  preview=Ui.note(owner,"");preview.setTag("loop-preview");preview.setTypeface(android.graphics.Typeface.MONOSPACE);preview.setTextIsSelectable(true);sheet.body.addView(preview);error=Ui.note(owner,"");error.setTextColor(Ui.danger());error.setTag("loop-error");sheet.body.addView(error);
  sheet.primary("Inserisci ciclo","check",this::save);insert=(Ui.Button)sheet.footer.getChildAt(sheet.footer.getChildCount()-1);insert.setTag("loop-insert");
  for(EditText edit:new EditText[]{variable,from,to,step,initialize,condition,body})edit.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int n){}public void onTextChanged(CharSequence s,int a,int b,int c){if(!loading)refresh();}public void afterTextChanged(Editable e){}});
  if(editing!=null){active=editing.kind;drafts[active]=editing.spec;targetButton.setVisibility(View.GONE);kindButton.setVisibility(View.GONE);rows.get(body).setVisibility(View.GONE);variable.setEnabled(false);insert.setText("Salva ciclo");sheet.action("Seleziona ciclo intero","select",0,()->{select.accept(editing.members);sheet.dismiss();});}load();targetLabel();
 }
 EditText field(String label,String value,boolean multiline,int max){LinearLayout row=Ui.column(owner);Ui.gap(row,10);row.addView(Ui.note(owner,label));EditText edit=Ui.edit(owner,value,label,multiline);edit.setFilters(new InputFilter[]{new InputFilter.LengthFilter(max)});row.addView(edit);fields.addView(row);rows.put(edit,row);return edit;}
 void read(){FlowLoopBuilder.Spec s=drafts[active];s.variable=variable.getText().toString();s.from=from.getText().toString();s.to=to.getText().toString();s.step=step.getText().toString();s.initialize=initialize.getText().toString();s.condition=condition.getText().toString();s.body=body.getText().toString();}
 void load(){loading=true;FlowLoopBuilder.Spec s=drafts[active];variable.setText(s.variable);from.setText(s.from);to.setText(s.to);step.setText(s.step);initialize.setText(s.initialize);condition.setText(s.condition);body.setText(s.body);for(View v:new View[]{variable,from,to,step})rows.get(v).setVisibility(active==0?View.VISIBLE:View.GONE);rows.get(initialize).setVisibility(active==0||editing!=null?View.GONE:View.VISIBLE);rows.get(condition).setVisibility(active==0?View.GONE:View.VISIBLE);kindButton.setText(new String[]{"Per · un intervallo di valori ▾","Mentre · controlla prima ▾","Ripeti · controlla alla fine ▾"}[active]);help.setText(active==0?"Gli estremi sono inclusi. Inizio, limite e passo sono calcolati una volta. Il contatore si aggiorna automaticamente.":active==1?"Controlla prima del corpo. Se la condizione è falsa, non esegue nessuna iterazione.":"Esegue il corpo almeno una volta. Poi continua mentre la condizione è vera. Aggiorna nel corpo le sue variabili.");if(editing!=null)help.setText("Modifica "+(active==0?"gli estremi e il passo":"la condizione")+". Corpo, rami, commenti e punti di interruzione vengono conservati. Seleziona ciclo include "+editing.members.size()+" blocchi. Il contatore si rinomina nei singoli blocchi.");loading=false;refresh();}
 void refresh(){read();if(editing!=null){error.setText("");preview.setText(active==0?"PER "+variable.getText()+" DA "+from.getText()+" A "+to.getText()+" PASSO "+step.getText()+" FAI\n    Corpo esistente nel foglio\nFINE PER":(active==1?"MENTRE ":"RIPETI · continua mentre ")+condition.getText()+"\n    Corpo esistente nel foglio");insert.setEnabled(true);return;}try{preview.setText(FlowLoopBuilder.source(drafts[active]));error.setText(choices.isEmpty()?"Collega almeno due blocchi per scegliere la freccia.":"");insert.setEnabled(!choices.isEmpty());}catch(IllegalArgumentException e){preview.setText("Completa i campi per vedere il ciclo.");error.setText(e.getMessage());insert.setEnabled(false);}}
 void chooseKind(){child=new Ui.Sheet(owner,"Tipo di ciclo","Scegli dove controllare la ripetizione.");String[] names={"Per · conteggio","Mentre · controlla prima","Ripeti · controlla alla fine"},details={"Un intervallo con contatore e passo, anche negativo.","Può eseguire il corpo zero volte.","Esegue il corpo almeno una volta."};for(int i=0;i<3;i++){final int kind=i;child.choice(names[i],details[i],Ui.accentInk(),()->{read();child.dismiss();active=kind;Ui.dismissKeyboard(body);load();Ui.enter(fields,0);});}child.show();}
 String label(Edge e){Document graph=FlowFunctionEditing.graph(project,functionId);Node a=graph.find(e.from),b=graph.find(e.to);return(a.kind==DECISION?"Ramo "+(e.branch.equals("true")?a.trueLabel:a.falseLabel)+" · ":"")+shortName(a)+" → "+shortName(b);}
 String shortName(Node n){String t=n.text.replace('\n',' ').trim();return t.isEmpty()?kindName(n.kind):t.length()>38?t.substring(0,35)+"…":t;}
 void targetLabel(){String text="Scegli una freccia";for(Edge e:choices)if(e.id.equals(edgeId))text=label(e);targetButton.setText("Inserisci su: "+text+" ▾");targetButton.setContentDescription("Freccia del ciclo: "+text);}
 void chooseTarget(){child=new Ui.Sheet(owner,"Dove inserire il ciclo","La freccia scelta continuerà nel ciclo, poi tornerà al percorso.");ListView list=new ListView(owner);list.setDivider(null);list.setAdapter(new BaseAdapter(){public int getCount(){return choices.size();}public Object getItem(int p){return choices.get(p);}public long getItemId(int p){return p;}public View getView(int p,View old,android.view.ViewGroup parent){TextView v=old instanceof TextView?(TextView)old:Ui.text(owner,"",16,true);Ui.pad(v,12,16,12,16);v.setText(label(choices.get(p)));return v;}});list.setOnItemClickListener((a,v,p,id)->{edgeId=choices.get(p).id;targetLabel();child.dismiss();});child.body.addView(list,new LinearLayout.LayoutParams(-1,Ui.dp(owner,320)));child.show();}
 void save(){try{read();FlowLoopBuilder.Plan plan=editing==null?FlowLoopBuilder.prepare(project,functionId,edgeId,drafts[active]):FlowCycle.prepare(project,functionId,editing,drafts[active]);apply.accept(plan);Ui.dismissKeyboard(body);sheet.dismiss();}catch(IllegalArgumentException e){error.setText(e.getMessage());error.setContentDescription(e.getMessage());Ui.enter(error,0);}}
 void close(){if(child!=null)child.dismiss();}
}
